class UserCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }
  static get observedAttributes() { return ['name']; }
  connectedCallback() { this.render(); }
  attributeChangedCallback() { this.render(); }
  render() {
    const name = this.getAttribute('name') || 'Unknown';
    this.shadowRoot.innerHTML =
      '<style>' +
      '  .card { border: 1px solid #cbd5e1; border-radius: 10px; padding: 14px; font-family: system-ui; }' +
      '  h3 { margin: 0 0 6px; color: #2563eb; }' +
      '  p { color: red; }' +
      '</style>' +
      '<div class="card"><h3>' + name + '</h3><slot></slot></div>';
  }
}
customElements.define('user-card', UserCard);

class CounterBadge extends HTMLElement {
  constructor() { super(); this.attachShadow({ mode: 'open' }); }
  static get observedAttributes() { return ['count']; }
  connectedCallback() { this.render(); }
  attributeChangedCallback() { this.render(); }
  render() {
    const c = this.getAttribute('count') || '0';
    this.shadowRoot.innerHTML =
      '<style>span{background:#2563eb;color:#fff;padding:4px 10px;border-radius:999px;font-family:system-ui}</style>' +
      '<span>Count: ' + c + '</span>';
  }
}
customElements.define('counter-badge', CounterBadge);

document.getElementById('inc').addEventListener('click', function () {
  const badge = document.querySelector('counter-badge');
  const next = Number(badge.getAttribute('count')) + 1;
  badge.setAttribute('count', String(next));
});

