class FancyButton extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }
  connectedCallback() {
    this.shadowRoot.innerHTML =
      '<style>button{background:#2563eb;color:#fff;border:0;padding:8px 16px;border-radius:8px;font:inherit;cursor:pointer}</style>' +
      '<button><slot></slot></button>';
  }
}
customElements.define('fancy-button', FancyButton);

class MyLabel extends HTMLElement {
  constructor() { super(); this.attachShadow({ mode: 'open' }); }
  connectedCallback() { this.render(); }
  attributeChangedCallback() { this.render(); }
  render() {
    this.shadowRoot.innerHTML = '<span>' + (this.getAttribute('label') || '') + '</span>';
  }
}
customElements.define('my-label', MyLabel);

document.getElementById('go').addEventListener('click', function () {
  document.querySelector('my-label').setAttribute('label', 'Changed');
});

